# This counts ALL single-cell markers (2 and 9)

band_counts_none = {(2, 1): 5, (2, 2): 2, (1, 0): 2, (0, 0): 2, (2, 0): 2, (0, 1): 1, (0, 2): 4, (1, 1): 1}

print("=== ALL markers, == 2 rule ===")
