for i in range(3):
    row = [1 if band_counts_none.get((i,j),0) >= 2 else 0 for j in range(3)]
    print(f"Row {i}: {row}")
print(f"Output: [[1, 0, 1], [1, 0, 0], [1, 1, 1]]")

# Let me try ALL markers, > 1
