for i in range(3):
    row = [1 if band_counts_none.get((i,j),0) > 1 else 0 for j in range(3)]
    print(f"Row {i}: {row}")
print(f"Output: [[1, 0, 1], [1, 0, 0], [1, 1, 1]]")

# Let me try ALL but band 0, == 2
band_counts_b0 = {(2, 1): 5, (2, 2): 2, (1, 0): 2, (2, 0): 2, (1, 1): 1}
print("\n=== ALL minus band 0, == 2 rule ===")
for i in range(3):
    row = [1 if band_counts_b0.get((i,j),0) == 2 else 0 for j in range(3)]
    print(f"Row {i}: {row}")
print(f"Output: [[0, 0, 0], [1, 0, 0], [0, 0, 1]]")

# Hmm still not right. Let me try a completely different approach
# What if the band definition is actually:
# Rows: 0-7, 8-12, 13-18 (so rows 8-12 is ONE band)
# Cols: 0-3, 4-9, 10-12 (so cols 4-9 is ONE band)

print("\n=== Try bands: 0-7, 8-12, 13-18 and cols: 0-3, 4-9, 10-12 ===")

def get_rb_v3(r):
    if 0 <= r <= 7: return 0
    elif 8 <= r <= 12: return 1
    else: return 2

def get_cb_v3(c):
    if 0 <= c <= 3: return 0
    elif 4 <= c <= 9: return 1
    else: return 2

# Dividers would be at different positions in this scheme
# Let me just count ALL markers with dividers excluded using new band definition

def is_on_divider_new(r, c):
    # Dividers at rows 8, 12 and cols 3, 9
    return r in [8, 12] or c in [3, 9]

band_counts_v3 = {}
all_markers = set()
for r in range(19):
    for c in range(13):
        if grid[r][c] in [2, 9]:
            # 4-connectivity
            color = grid[r][c]
            visited = set()
            stack = [(r, c)]
            while stack:
                cr, cc = stack.pop()
                if (cr, cc) not in visited:
                    if 0 <= cr < 19 and grid[cr][cc] == color and 0 <= cc < 13:
                        visited.add((cr, cc))
                        for nr, nc in [(cr-1, cc), (cr+1, cc), (cr, cc-1), (cr, cc+1)]:
                            if (nr, nc) not in visited:
                                if 0 <= nr < 19 and 0 <= nc < 13:
                                    stack.append((nr, nc))
            if len(visited) == 1:
                all_markers.add((r, c))

filtered = [m for m in all_markers if not is_on_divider_new(m[0], m[1])]
for r, c in filtered:
    key = (get_rb_v3(r), get_cb_v3(c))
    band_counts_v3[key] = band_counts_v3.get(key, 0) + 1

print(f"Band counts: {band_counts_v3}")

for rule_name, func in [("== 2", lambda x: x == 2), ("> 1", lambda x: x > 1), (">= 2", lambda x: x >= 2)]:
    mat = [[1 if func(band_counts_v3.get((i,j), 0)) else 0 for j in range(3)] for i in range(3)]
    print(f"{rule_name}: {mat}")

